import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { REQUEST_ERROR } from "../../errors/error-registry.js";
import { encodeWorkflowPathSegment, normalizeWorkflowApiBase, useStableWorkflowHeaders, workflowJsonMutationHeaders, } from "./mutation-headers.js";
/** Manage workflow approval interactions. */
export function useApproval(options) {
    const { runId, approvalId, apiBase = "/api/workflows", headers, credentials, approver = "unknown", onDecision, onError, } = options;
    const normalizedApiBase = normalizeWorkflowApiBase(apiBase);
    const stableHeaders = useStableWorkflowHeaders(headers);
    const requestContext = useMemo(() => ({ approvalId, credentials, normalizedApiBase, runId, stableHeaders }), [approvalId, credentials, normalizedApiBase, runId, stableHeaders]);
    const currentRequestContext = useRef(requestContext);
    currentRequestContext.current = requestContext;
    const decisionRequestContext = useRef(requestContext);
    const activeDecision = useRef(null);
    const [approvalState, setApprovalState] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState(null);
    const toError = useCallback((err) => {
        return err instanceof Error ? err : new Error(String(err));
    }, []);
    useEffect(() => {
        if (decisionRequestContext.current === requestContext)
            return;
        decisionRequestContext.current = requestContext;
        setIsSubmitting(false);
    }, [requestContext]);
    useEffect(() => {
        if (!runId || !approvalId)
            return;
        const controller = new AbortController();
        let current = true;
        setApprovalState(null);
        setError(null);
        setIsLoading(true);
        async function fetchApproval() {
            try {
                const response = await fetch(`${normalizedApiBase}/runs/${encodeWorkflowPathSegment(runId, "Workflow run ID")}/approvals/${encodeWorkflowPathSegment(approvalId, "Workflow approval ID")}`, { signal: controller.signal, headers: stableHeaders, credentials });
                if (!response.ok) {
                    throw REQUEST_ERROR.create({
                        detail: `Failed to fetch approval: ${response.status}`,
                        status: response.status,
                    });
                }
                const data = await response.json();
                if (!current)
                    return;
                setApprovalState({ approval: data, requestContext });
                setError(null);
            }
            catch (err) {
                if (!current || controller.signal.aborted)
                    return;
                const fetchError = toError(err);
                setError(fetchError);
                onError?.(fetchError);
            }
            finally {
                if (current)
                    setIsLoading(false);
            }
        }
        void fetchApproval();
        return () => {
            current = false;
            controller.abort();
        };
    }, [
        runId,
        approvalId,
        credentials,
        normalizedApiBase,
        onError,
        requestContext,
        stableHeaders,
        toError,
    ]);
    const submitDecision = useCallback((decision) => {
        if (!runId || !approvalId)
            return Promise.resolve();
        if (activeDecision.current?.requestContext === requestContext) {
            return activeDecision.current.promise;
        }
        decisionRequestContext.current = requestContext;
        const submittedRequestContext = requestContext;
        const isCurrentRequest = () => submittedRequestContext === currentRequestContext.current;
        const decisionId = {};
        setIsSubmitting(true);
        setError(null);
        const promise = Promise.resolve().then(async () => {
            try {
                const requestUrl = `${normalizedApiBase}/runs/${encodeWorkflowPathSegment(runId, "Workflow run ID")}/approvals/${encodeWorkflowPathSegment(approvalId, "Workflow approval ID")}`;
                const response = await fetch(requestUrl, {
                    method: "POST",
                    headers: workflowJsonMutationHeaders(requestUrl, stableHeaders),
                    credentials,
                    body: JSON.stringify(decision),
                });
                if (!response.ok) {
                    throw REQUEST_ERROR.create({
                        detail: `Failed to submit decision: ${response.status}`,
                        status: response.status,
                    });
                }
                const responseText = await response.text();
                let responseBody;
                if (responseText) {
                    try {
                        responseBody = JSON.parse(responseText);
                    }
                    catch {
                        // Successful legacy/proxied endpoints may return a non-JSON body.
                    }
                }
                const responseResolvedBy = responseBody !== null && typeof responseBody === "object" &&
                    "resolvedBy" in responseBody
                    ? responseBody.resolvedBy
                    : undefined;
                const resolvedDecision = {
                    ...decision,
                    approver: typeof responseResolvedBy === "string"
                        ? responseResolvedBy
                        : decision.approver,
                };
                if (!isCurrentRequest())
                    return;
                setApprovalState((prev) => {
                    if (!prev || prev.requestContext !== submittedRequestContext)
                        return prev;
                    return {
                        requestContext: prev.requestContext,
                        approval: {
                            ...prev.approval,
                            status: decision.approved ? "approved" : "rejected",
                            resolvedAt: new Date(),
                            resolvedBy: resolvedDecision.approver,
                            comment: decision.comment,
                        },
                    };
                });
                onDecision?.(resolvedDecision);
            }
            catch (err) {
                const submitError = toError(err);
                if (isCurrentRequest()) {
                    setError(submitError);
                    onError?.(submitError);
                }
                throw submitError;
            }
            finally {
                if (activeDecision.current?.id === decisionId)
                    activeDecision.current = null;
                if (isCurrentRequest())
                    setIsSubmitting(false);
            }
        });
        activeDecision.current = { id: decisionId, promise, requestContext };
        return promise;
    }, [
        runId,
        approvalId,
        credentials,
        normalizedApiBase,
        onDecision,
        onError,
        requestContext,
        stableHeaders,
        toError,
    ]);
    const approve = useCallback(async (comment, data) => {
        return submitDecision({ approved: true, approver, comment, data });
    }, [submitDecision, approver]);
    const reject = useCallback(async (comment, data) => {
        return submitDecision({ approved: false, approver, comment, data });
    }, [submitDecision, approver]);
    const approval = approvalState?.requestContext === requestContext ? approvalState.approval : null;
    const isPending = approval?.status === "pending";
    return {
        approval,
        approve,
        reject,
        submitDecision,
        isSubmitting,
        isLoading,
        error,
        isPending,
        isResolved: !isPending,
    };
}
